// Auto-generated anatomical 3D brain pointcloud with Pure White #FFFFFF replaced by Deep Black #000000:
// Electric Violet #8B35FF, Neon Purple #B44CFF, Cyan Blue #00CFFF, Electric Blue #286BFF,
// Magenta #FF35B8, Teal #00C9A7, Amber Gold #FFB900, Deep Black #000000
export const ANATOMICAL_BRAIN_VERTEX_COUNT = 16000;
export const ANATOMICAL_BRAIN_DATA_B64 = "";

export function getAnatomicalBrainData() {
  const bin = atob(ANATOMICAL_BRAIN_DATA_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  const totalFloats = ANATOMICAL_BRAIN_VERTEX_COUNT;
  let offset = 0;
  
  const positions = new Float32Array(bytes.buffer, offset, totalFloats * 3);
  offset += totalFloats * 3 * 4;
  
  const colors = new Float32Array(bytes.buffer, offset, totalFloats * 3);
  offset += totalFloats * 3 * 4;
  
  const sizes = new Float32Array(bytes.buffer, offset, totalFloats);
  offset += totalFloats * 4;
  
  const angles = new Float32Array(bytes.buffer, offset, totalFloats);
  
  return { count: totalFloats, positions, colors, sizes, angles };
}
